 $('batch-open').onclick=()=>{$('batch-dialog').showModal();renderBatch();};$('batch-close').onclick=()=>$('batch-dialog').close();$('batch-cancel').onclick=cancel;for(const id of ['batch-dialog','trim-dialog'])$(id).addEventListener('cancel',e=>{if(busy){e.preventDefault();cancel();}});
 $('batch-review').onclick=()=>{const ns=selectedPages();operation(async()=>{for(const n of ns){checkCancel();$('batch-status').textContent=`Revisando hoja ${n+1} de ${model.pages}…`;await reviewPage(n);}checkCancel();$('batch-status').textContent='Revisión terminada. Abrí cada hoja para comprobar sus bordes y aprobá los avisos que correspondan.';}).finally(renderBatch);};
 $('batch-export').onclick=()=>{const ns=selectedPages();operation(async()=>{const files=[];let bytes=0;for(const n of ns){checkCancel();$('batch-status').textContent=`Codificando y verificando hoja ${n+1}…`;const blob=await exportPage(n);bytes+=blob.size;if(bytes>512*1024*1024)throw Error('El lote supera 512 MB. Descargá las hojas por separado. No se redujo la resolución.');files.push({name:exportName(n),data:new Uint8Array(await blob.arrayBuffer())});}checkCancel();const zip=W.zip(files);checkCancel();download(zip,'momotus-pliegos-300dpi.zip');$('batch-status').textContent=`${files.length} PNG verificados incluidos en el ZIP. El tamaño físico y el alfa coinciden con la revisión.`;}).finally(renderBatch);};

 window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});render();requestAnimationFrame(fitView);
